exploreUrl:
@js:
var s = [];
function p(t, u, w){ s.push({title:t, url:u, style:{layout_flexGrow:1, layout_flexBasisPercent:w}}); }
function qs(k, u){ var m = (u || '').match(new RegExp('[?&]' + k + '=([^&]*)')); return m ? decodeURIComponent(m[1]) : ''; }
var config = {};
try { config = JSON.parse(source.getVariable() || '{}'); } catch(e) {}
var gender = config.gender || '男频';
s.push({title:"⚧ 频道", type:"select", chars:["男频","女频"], default:gender,
  action:"(function(){var c={};try{c=JSON.parse(source.getVariable()||'{}');}catch(e){}c.gender=infoMap['⚧ 频道']||'男频';source.setVariable(JSON.stringify(c));java.refreshExplore();})()",
  style:{layout_flexGrow:1, layout_flexBasisPercent:1}});
try {
  var sceneId = (gender === '女频') ? 282 : 281;
  var catUrl = "https://api.midureader.com/fiction/scene/getCategoryV4," + JSON.stringify({method:"POST", body:"app=midu&id=" + sceneId});
  var catResp = String(java.ajax(catUrl) || '');
  var catJson = JSON.parse(catResp);
  var tags = (catJson && catJson.data && catJson.data.config && catJson.data.config.tagsV3) || [];
  for (var i = 0; i < tags.length; i++) {
    var t = tags[i] || {};
    var name = String(t.name || '').trim();
    var type = t.type;
    if (!name || type === '2') continue;
    var link = t.link || '';
    var sc = qs('secondChannelId', link);
    var tg = qs('tagId', link);
    var url;
    if (sc) {
      // 主分类：分类书单接口（second_channel 过滤准确）
      url = "https://api.midureader.com/fiction/search/channel," + JSON.stringify({method:"POST", body:"app=midu&second_channel=" + sc + "&status=&rank=&page={{page-1}}"});
    } else if (tg) {
      // 流派/题材/风格/角色/热门 等标签：关键词搜索
      url = "https://api.midureader.com/fiction/search/search," + JSON.stringify({method:"POST", body:"app=midu&keyword=" + encodeURIComponent(name) + "&page={{page-1}}"});
    } else {
      continue;
    }
    p(name, url, 0.4);
  }
} catch(e) {}
JSON.stringify(s);

